INSERT INTO `wp_comments` (`comment_ID`, `comment_post_ID`, `comment_author`, `comment_author_email`, `comment_author_url`, `comment_author_IP`, `comment_date`, `comment_date_gmt`, `comment_content`, `comment_karma`, `comment_approved`, `comment_agent`, `comment_type`, `comment_parent`, `user_id`) VALUES
(1, 1, 'Bir WordPress yorumcusu', 'wapuu@wordpress.example', 'https://tr.wordpress.org/', '', '2026-11-01 15:39:03', '2026-11-01 12:39:03', 'Merhaba, bu bir yorumdur.\nYorum yönetimine başlamak, düzenlemek ve silmek için lütfen Başlangıç ekranındaki yorumlar bölümüne gidin.\nYorumcuların avatarları <a href=\"https://gravatar.com/\">Gravatar</a> üzerinden alınır.', 0, '1', '', 'comment', 0, 0);
